USE master;
GO

IF DB_ID(N'UniversityDocumentDB') IS NOT NULL
BEGIN
    ALTER DATABASE UniversityDocumentDB SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE UniversityDocumentDB;
END
GO

CREATE DATABASE UniversityDocumentDB;
GO

USE UniversityDocumentDB;
GO

CREATE TABLE dbo.UniversityCollection
(
    Id INT IDENTITY(1,1) PRIMARY KEY,
    Document JSON NOT NULL,
    CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME()
);
GO

GO

SELECT COUNT(*) AS TotalUniversityDocuments FROM dbo.UniversityCollection;
GO

SELECT TOP (5)
    Id,
    JSON_VALUE(Document, '$.universityId') AS UniversityId,
    JSON_VALUE(Document, '$.universityName') AS UniversityName,
    JSON_VALUE(Document, '$.location.city') AS City,
    JSON_VALUE(Document, '$.location.state') AS State
FROM dbo.UniversityCollection;
GO
